#if UNITY_EDITOR
namespace Game.EditorTools { internal static class TutorialDescriptions {
public const string Financial = "Você já tem capital próprio para começar. Pode contratar um financiamento agora ou seguir sem empréstimo e voltar ao Banco durante o primeiro ou o segundo mês. No terceiro mês, novas contratações não são permitidas.\n\nDepois de contratado, o financiamento não pode ser trocado. Selecionar um cartão ainda não contrata: revise os valores e confirme.\n\nValor disponível: quantia integral que será adicionada ao caixa ao contratar.\nJuros ao mês: percentual cobrado sobre o saldo devedor em cada mês.\nPrazo: meses restantes até o fim do trimestre para pagar.\nParcela: parte do principal mais os juros sobre o saldo devedor; o valor diminui conforme a dívida é paga.\nCapital inicial: seus recursos próprios, sem incluir o empréstimo.";
public const string Equipment = "Esta é a loja de equipamentos. Neste primeiro acesso, você verá apenas o kit básico e dois exemplos do catálogo.\n\nAdicione o kit básico ao carrinho, abra o Carrinho, confira os itens e o saldo e conclua a compra. O kit é obrigatório para avançar para a equipe. Seu capital próprio permite comprá-lo sem financiamento.\n\nEquipamentos comuns compõem a estrutura básica. Os específicos aparecem como premium e dependem do tipo de restaurante. O preço é pago uma única vez, na compra.\n\nOs bônus de capacidade ampliam o atendimento e os de qualidade ajudam a reputação quando o atendimento do mês é satisfatório. O selo premium, sozinho, não garante aumento de vendas.";
public const string Team = "Esta é a tela de contratação de funcionários. Comece com a equipe mínima do seu restaurante, indicada nesta tela. Confirme a contratação para concluir a preparação.\n\nCada novo funcionário aumenta a folha salarial mensal. Conforme a função, também acrescenta capacidade de atendimento e contribuição de qualidade. A qualidade ajuda a reputação quando o atendimento do mês é satisfatório.\n\nMais capacidade não garante mais vendas: o resultado depende da demanda, do espaço e dos equipamentos. O gerente contribui para a qualidade, mas não acrescenta capacidade.\n\nDepois, no RH do menu, você poderá contratar mais funcionários. Os cartões mostram o custo mensal e os efeitos de cada contratação.";
} }
#endif